#!/bin/env bash

# https://codeberg.org/librewolf/issues/issues/2847

# Merges packaged policies + local overlay; overlay wins on conflicts.
# Regenerated by the pacman hook so it keeps tracking upstream defaults.
set -euo pipefail
src=/usr/lib/librewolf/distribution/policies.json
dst=/etc/librewolf/policies/policies.json
overlay=/etc/librewolf/policies/overlay.json
mkdir -p /etc/librewolf/policies
jq -s '.[0] * .[1]' "$src" "$overlay" > "$dst.tmp" && mv "$dst.tmp" "$dst"
